  "inlineSchema": "// This is your Prisma schema file\n// Learn more: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── USERS ────────────────────────────────────────────────────────────\nmodel User {\n  id              String   @id @default(uuid())\n  name            String\n  email           String   @unique\n  passwordHash    String   @map(\"password_hash\")\n  schoolId        String?  @map(\"school_id\")\n  class_          String?  @map(\"class\")\n  gender          String? // 'L' | 'P'\n  age             Int?\n  profileImageUrl String?  @map(\"profile_image_url\")\n  schoolLevel     String?  @map(\"school_level\") // SD | SMP | SMA | SMK\n  createdAt       DateTime @default(now()) @map(\"created_at\")\n  updatedAt       DateTime @updatedAt @map(\"updated_at\")\n\n  school         School?          @relation(fields: [schoolId], references: [id])\n  scanHistories  ScanHistory[]\n  dailyNutrition DailyNutrition[]\n\n  @@map(\"users\")\n}\n\n// ─── SCHOOLS ─────────────────────────────────────────────────────────\nmodel School {\n  id      String  @id @default(uuid())\n  name    String\n  level   String // SD | SMP | SMA | SMK\n  address String?\n  city    String?\n\n  users    User[]\n  mbgMenus MbgMenu[]\n\n  @@map(\"schools\")\n}\n\n// ─── FOODS ───────────────────────────────────────────────────────────\nmodel Food {\n  id          String  @id @default(uuid())\n  name        String\n  category    String // Karbohidrat | Protein Hewani | Protein Nabati | Sayuran | Buah | Minuman\n  imageUrl    String? @map(\"image_url\")\n  description String?\n  isActive    Boolean @default(true) @map(\"is_active\")\n\n  nutrition   Nutrition?\n  menuItems   MbgMenuItem[]\n  predictions Prediction[]\n\n  @@map(\"foods\")\n}\n\n// ─── NUTRITION ───────────────────────────────────────────────────────\nmodel Nutrition {\n  id          String @id @default(uuid())\n  foodId      String @unique @map(\"food_id\")\n  calories    Float // kcal per 100g\n  protein     Float // g per 100g\n  carbs       Float // g per 100g\n  fat         Float // g per 100g\n  fiber       Float // g per 100g\n  sugar       Float  @default(0)\n  sodium      Float  @default(0)\n  calcium     Float  @default(0)\n  iron        Float  @default(0)\n  vitaminC    Float  @default(0) @map(\"vitamin_c\")\n  vitaminA    Float  @default(0) @map(\"vitamin_a\")\n  portionGram Float  @default(100) @map(\"portion_gram\")\n\n  food Food @relation(fields: [foodId], references: [id])\n\n  @@map(\"nutrition\")\n}\n\n// ─── MBG MENUS ───────────────────────────────────────────────────────\nmodel MbgMenu {\n  id       String   @id @default(uuid())\n  schoolId String   @map(\"school_id\")\n  date     DateTime @db.Date\n  dayName  String   @map(\"day_name\")\n\n  school School        @relation(fields: [schoolId], references: [id])\n  items  MbgMenuItem[]\n\n  @@unique([schoolId, date])\n  @@map(\"mbg_menus\")\n}\n\nmodel MbgMenuItem {\n  id          String @id @default(uuid())\n  menuId      String @map(\"menu_id\")\n  foodId      String @map(\"food_id\")\n  portionGram Float  @default(100) @map(\"portion_gram\")\n\n  menu MbgMenu @relation(fields: [menuId], references: [id])\n  food Food    @relation(fields: [foodId], references: [id])\n\n  @@map(\"mbg_menu_items\")\n}\n\n// ─── SCAN HISTORY ─────────────────────────────────────────────────────\nmodel ScanHistory {\n  id            String   @id @default(uuid())\n  userId        String   @map(\"user_id\")\n  imageUrl      String?  @map(\"image_url\")\n  scannedAt     DateTime @default(now()) @map(\"scanned_at\")\n  totalCalories Float    @default(0) @map(\"total_calories\")\n  totalProtein  Float    @default(0) @map(\"total_protein\")\n  totalCarbs    Float    @default(0) @map(\"total_carbs\")\n  totalFat      Float    @default(0) @map(\"total_fat\")\n  totalFiber    Float    @default(0) @map(\"total_fiber\")\n  status        String   @default(\"success\") // success | failed | processing\n\n  // Data Sensorik — indikator penerimaan makanan (bukan kandungan gizi)\n  // { taste, salt_level, sweet_level, texture, aroma }\n  sensoryData Json? @map(\"sensory_data\")\n\n  // Data Konsumsi — { portion_size, leftover_amount, is_finished }\n  consumptionData Json? @map(\"consumption_data\")\n\n  user        User         @relation(fields: [userId], references: [id])\n  predictions Prediction[]\n\n  @@map(\"scan_history\")\n}\n\n// ─── PREDICTIONS ──────────────────────────────────────────────────────\nmodel Prediction {\n  id                  String @id @default(uuid())\n  scanId              String @map(\"scan_id\")\n  foodId              String @map(\"food_id\")\n  confidence          Float\n  portionEstimateGram Float  @default(100) @map(\"portion_estimate_gram\")\n  calories            Float?\n  protein             Float?\n  carbs               Float?\n  fat                 Float?\n\n  scan ScanHistory @relation(fields: [scanId], references: [id])\n  food Food        @relation(fields: [foodId], references: [id])\n\n  @@map(\"predictions\")\n}\n\n// ─── DAILY NUTRITION ──────────────────────────────────────────────────\nmodel DailyNutrition {\n  id             String   @id @default(uuid())\n  userId         String   @map(\"user_id\")\n  date           DateTime @db.Date\n  totalCalories  Float    @default(0) @map(\"total_calories\")\n  totalProtein   Float    @default(0) @map(\"total_protein\")\n  totalCarbs     Float    @default(0) @map(\"total_carbs\")\n  totalFat       Float    @default(0) @map(\"total_fat\")\n  totalFiber     Float    @default(0) @map(\"total_fiber\")\n  totalScans     Int      @default(0) @map(\"total_scans\")\n  caloriesTarget Float    @default(2000) @map(\"calories_target\")\n  proteinTarget  Float    @default(60) @map(\"protein_target\")\n\n  user User @relation(fields: [userId], references: [id])\n\n  @@unique([userId, date])\n  @@map(\"daily_nutrition\")\n}\n",
